-- FilmNova unified database installer / upgrader
-- Import this single file into the FilmNova database. It is designed to be repeatable.
CREATE DATABASE IF NOT EXISTS phim_web CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE phim_web;

CREATE TABLE IF NOT EXISTS settings(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,`key` VARCHAR(100) UNIQUE NOT NULL,value TEXT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(100) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role VARCHAR(30) NOT NULL DEFAULT 'user',display_name VARCHAR(150),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS movies(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL,slug VARCHAR(255) UNIQUE NOT NULL,origin_name VARCHAR(255),thumb_url TEXT,poster_url TEXT,type VARCHAR(100),status VARCHAR(100),year SMALLINT,time VARCHAR(100),quality VARCHAR(100),lang VARCHAR(255),categories TEXT,countries TEXT,description MEDIUMTEXT,director TEXT,actors TEXT,trailer_url TEXT,view_count BIGINT UNSIGNED NOT NULL DEFAULT 0,episodes_count INT UNSIGNED NOT NULL DEFAULT 0,is_featured TINYINT(1) NOT NULL DEFAULT 0,is_hidden TINYINT(1) NOT NULL DEFAULT 0,source_type VARCHAR(30) NOT NULL DEFAULT 'api',source_json LONGTEXT,updated_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS episodes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,movie_id INT UNSIGNED NOT NULL,server_name VARCHAR(255) DEFAULT 'Server 1',season INT NOT NULL DEFAULT 1,episode_number INT NOT NULL DEFAULT 0,name VARCHAR(255),stream_url TEXT,embed_url TEXT,raw_json LONGTEXT,source_type VARCHAR(30) NOT NULL DEFAULT 'api',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(movie_id) REFERENCES movies(id) ON DELETE CASCADE,INDEX idx_episode(movie_id,server_name,season,episode_number)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS banners(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(255),subtitle VARCHAR(255),image_url TEXT,link_url TEXT,position VARCHAR(40) DEFAULT 'home',button_text VARCHAR(80),active TINYINT(1) DEFAULT 1,sort_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sync_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sync_type VARCHAR(50),message TEXT,items INT DEFAULT 0,created_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS view_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,movie_id INT UNSIGNED NOT NULL,visitor_key CHAR(64) NOT NULL,view_day DATE NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,INDEX idx_view_movie_day(movie_id,view_day),UNIQUE KEY uq_view_once(movie_id,visitor_key,view_day),FOREIGN KEY(movie_id) REFERENCES movies(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS movie_ratings(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,movie_id INT UNSIGNED NOT NULL,visitor_key CHAR(64) NOT NULL,rating TINYINT UNSIGNED NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_rating_visitor(movie_id,visitor_key),INDEX idx_rating_movie(movie_id),FOREIGN KEY(movie_id) REFERENCES movies(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS comment_accounts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,display_name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,pin_hash VARCHAR(255) NOT NULL,auth_token_hash VARCHAR(255) NULL,last_login_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_token(auth_token_hash(32))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS comments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,movie_id INT UNSIGNED NOT NULL,account_id BIGINT UNSIGNED NOT NULL,parent_id BIGINT UNSIGNED NULL,display_name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,body TEXT NOT NULL,original_body TEXT NULL,reaction_icon VARCHAR(16) NULL,reaction_icon_animated TINYINT(1) NOT NULL DEFAULT 0,moderation_score INT NOT NULL DEFAULT 0,moderation_status ENUM('published','hidden','deleted') NOT NULL DEFAULT 'published',flag_reason VARCHAR(255) NULL,deleted_at DATETIME NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(movie_id) REFERENCES movies(id) ON DELETE CASCADE,FOREIGN KEY(account_id) REFERENCES comment_accounts(id) ON DELETE CASCADE,FOREIGN KEY(parent_id) REFERENCES comments(id) ON DELETE SET NULL,INDEX idx_comments_movie(movie_id,moderation_status,created_at),INDEX idx_comments_email(email),INDEX idx_comments_parent(parent_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS comment_reactions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,comment_id BIGINT UNSIGNED NOT NULL,account_id BIGINT UNSIGNED NOT NULL,reaction_type VARCHAR(30) NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(comment_id) REFERENCES comments(id) ON DELETE CASCADE,FOREIGN KEY(account_id) REFERENCES comment_accounts(id) ON DELETE CASCADE,UNIQUE KEY uq_comment_reaction(comment_id,account_id,reaction_type),INDEX idx_reaction_comment(comment_id,reaction_type)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS comment_bans(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL,reason VARCHAR(255),starts_at DATETIME DEFAULT CURRENT_TIMESTAMP,ends_at DATETIME NULL,permanent TINYINT(1) NOT NULL DEFAULT 0,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,created_by VARCHAR(100) NULL,INDEX idx_ban_email(email)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS moderation_terms(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,term VARCHAR(120) NOT NULL UNIQUE,category VARCHAR(50) DEFAULT 'negative',weight INT NOT NULL DEFAULT 1,source VARCHAR(30) NOT NULL DEFAULT 'default',active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,INDEX idx_term_active(active)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS moderation_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,comment_id BIGINT UNSIGNED NULL,email VARCHAR(190) NULL,action VARCHAR(50) NOT NULL,reason VARCHAR(255),score INT NOT NULL DEFAULT 0,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,INDEX idx_mod_email(email),INDEX idx_mod_created(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Safe migrations for existing installations.
DELIMITER $$
CREATE PROCEDURE filmnova_add_column_if_missing()
BEGIN
  IF NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='movies' AND COLUMN_NAME='local_media_version') THEN ALTER TABLE movies ADD COLUMN local_media_version VARCHAR(40) NULL; END IF;
  IF NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='movies' AND COLUMN_NAME='api_image_source') THEN ALTER TABLE movies ADD COLUMN api_image_source VARCHAR(255) NULL; END IF;
  IF NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='episodes' AND COLUMN_NAME='source_type') THEN ALTER TABLE episodes ADD COLUMN source_type VARCHAR(30) NOT NULL DEFAULT 'api'; END IF;
  IF NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='comments' AND COLUMN_NAME='parent_id') THEN ALTER TABLE comments ADD COLUMN parent_id BIGINT UNSIGNED NULL; END IF;
  IF NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='comments' AND COLUMN_NAME='deleted_at') THEN ALTER TABLE comments ADD COLUMN deleted_at DATETIME NULL; END IF;
  IF NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='comments' AND COLUMN_NAME='reaction_icon') THEN ALTER TABLE comments ADD COLUMN reaction_icon VARCHAR(16) NULL; END IF;
  IF NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='comments' AND COLUMN_NAME='reaction_icon_animated') THEN ALTER TABLE comments ADD COLUMN reaction_icon_animated TINYINT(1) NOT NULL DEFAULT 0; END IF;
END$$
CALL filmnova_add_column_if_missing()$$
DROP PROCEDURE filmnova_add_column_if_missing$$
DELIMITER ;

